 if(el.id==='stock-file'){stockReadVersion++;stockPreview=null;stockUpload=null;$('#stock-map').innerHTML='';const file=el.files[0];if(file){if(file.size>10*1024*1024)throw Error('Maximum upload is 10 MB.');await readStockFile(file.name,await fileBase64(file));}}
 if(el.id==='stock-sheet'||el.id==='stock-header')stockColumns();
